theme.css:
/* ==== INTERFACE ====
   材质   两汉简帛石刻与史官丹朱：以冷素青宣（#EFF2EE）为底托举焦墨叙事（#18201E），以史笔丹砂（#B83324）凸显太史公曰，以青石竹墨（#244C5A与#366552）勾勒本纪列传互见之网；字体以典籍雕版之Noto Serif CJK SC与手书风骨之LXGW WenKai辉映。
   token  --bg #EFF2EE        画布底色｜全域背景（冷素青宣）
   token  --surface #F8FAF7   卡片与释读底色｜文本阅读区、对勘卡片底色
   token  --text #18201E      正文字色｜主体字、典籍原本正文字
   token  --muted #64736E     次级文字与分界线｜结构线、编卷标尺、按语
   token  --taishi #B83324    太史公曰强调色｜史公断语、朱批、情感论赞焦点
   token  --cross-ref #244C5A 互见法主脉色｜主传定位、本纪主线、核心叙事实体
   token  --supplement #366552 互见法支脉色｜他传穿插、列传补笔、边缘叙事视角
   token  --focus #B83324     交互聚焦色｜焦点外圈、操作中高亮
   token  --font-serif        引文与标题字族｜'Noto Serif CJK SC', serif
   token  --font-sans         UI标签字族｜'Noto Sans CJK SC', sans-serif
   token  --font-calli        赞语评述字族｜'LXGW WenKai', 'AR PL KaitiM GB', serif
   token  --fs-h1 34px        页标题
   token  --fs-h2 22px        区块标题
   token  --fs-lead 19px      导语
   token  --fs-body 18px      正文与原本句
   token  --fs-sec 16px       次级解说与对勘文字
   token  --fs-label 15px     功能标签与卷次徽章
   token  --fs-tick 13px      纯数字刻度与篇卷序号
   版心   1488×844           #stage 已含 padding
   版式   .focus             标题后单一主区
   ==== /INTERFACE ==== */

:root {
  --pad-x: 56px;
  --pad-y: 28px;
  --bg: #EFF2EE;
  --surface: #F8FAF7;
  --text: #18201E;
  --muted: #64736E;
  --taishi: #B83324;
  --cross-ref: #244C5A;
  --supplement: #366552;
  --focus: #B83324;
  --font-serif: 'Noto Serif CJK SC', serif;
  --font-sans: 'Noto Sans CJK SC', sans-serif;
  --font-calli: 'LXGW WenKai', 'AR PL KaitiM GB', serif;
  --fs-h1: 34px;
  --fs-h2: 22px;
  --fs-lead: 19px;
  --fs-body: 18px;
  --fs-sec: 16px;
  --fs-label: 15px;
  --fs-tick: 13px;
}

#stage {
  display: flex;
  flex-direction: column;
  padding: var(--pad-y) var(--pad-x);
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--font-serif);
}

.focus {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

svg .bar, svg .cell, svg .box {
  width: auto;
  height: auto;
}
